(4777658, 689684, 91496, '<td valign="top">Very nice.  I like the irregular patterns and colors.  Border actually enhances this photo.</td>', 'Very nice.  I like the irregular patterns and colors.  Border actually enhances this photo.', '2008-06-20 13:04:11.000000', NULL, 1),
(4777659, 688061, 91496, '<td valign="top">Lighting is great.  Pose and compositons ooze sucess.</td>', 'Lighting is great.  Pose and compositons ooze sucess.', '2008-06-20 13:04:47.000000', NULL, 1),
(4777661, 689771, 94837, '<td valign="top">Almost success anyways.  I''m assuming he caught it?  Nice shot, especially the monochromaticness.</td>', 'Almost success anyways.  I''m assuming he caught it?  Nice shot, especially the monochromaticness.', '2008-06-20 13:05:02.000000', NULL, 1),
(4777662, 689808, 91496, '<td valign="top">Love the panic/relief in the eyes.</td>', 'Love the panic/relief in the eyes.', '2008-06-20 13:05:19.000000', NULL, 1),
(4777663, 688061, 94837, '<td valign="top">That looks like the cover of a book or DVD case.  Awesome lighting!</td>', 'That looks like the cover of a book or DVD case.  Awesome lighting!', '2008-06-20 13:05:43.000000', NULL, 1),
(4777665, 689771, 91496, '<td valign="top">Nice capture.  The angle of the body really shows the movement.</td>', 'Nice capture.  The angle of the body really shows the movement.', '2008-06-20 13:06:10.000000', NULL, 1),
(4777667, 689528, 94837, '<td valign="top">A number of chess photographs in this competition, I think I like this one the most so far.  It''s clean and simple but still conveys the idea.</td>', 'A number of chess photographs in this competition, I think I like this one the most so far.  It''s clean and simple but still conveys the idea.', '2008-06-20 13:07:17.000000', NULL, 1),
(4777668, 689231, 91496, '<td valign="top">Nice idea, although the success theme is not that strong.  Focus is off.  Not a fan of the border.</td>', 'Nice idea, although the success theme is not that strong.  Focus is off.  Not a fan of the border.', '2008-06-20 13:07:56.000000', NULL, 1),
(4777670, 689465, 94837, '<td valign="top">Now that''s what I call success!  The colors are nice as well.</td>', 'Now that''s what I call success!  The colors are nice as well.', '2008-06-20 13:08:35.000000', NULL, 1),
(4777671, 688968, 91496, '<td valign="top">Nice colors contrast on the two helmets.  Success theme is not very obvious.</td>', 'Nice colors contrast on the two helmets.  Success theme is not very obvious.', '2008-06-20 13:08:52.000000', NULL, 1),
(4777672, 689684, 94837, '<td valign="top">Has the feel of one of those motivational posters that are over the place these days.  I like it.</td>', 'Has the feel of one of those motivational posters that are over the place these days.  I like it.', '2008-06-20 13:09:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4777673, 689027, 91496, '<td valign="top">Very nice reflections.  Not a fan of the border.  Success theme is not very obvious.</td>', 'Very nice reflections.  Not a fan of the border.  Success theme is not very obvious.', '2008-06-20 13:09:27.000000', NULL, 1),
(4777674, 689456, 91496, '<td valign="top">Pretty flower.  Focus is a bit off.  Blown highlights on the leaf.  Success theme is not very obvious.</td>', 'Pretty flower.  Focus is a bit off.  Blown highlights on the leaf.  Success theme is not very obvious.', '2008-06-20 13:10:19.000000', NULL, 1),
(4777675, 688550, 94837, '<td valign="top">Very strong contrast, is the building that white naturally?</td>', 'Very strong contrast, is the building that white naturally?', '2008-06-20 13:11:42.000000', NULL, 1),
(4777697, 689334, 66384, '<td valign="top">I know the feeling. I had such a feeling of accomplishment when I captured my first lightening bolt. Good topic. And congratulations. I''m not crazy about the purple tone though.</td>', 'I know the feeling. I had such a feeling of accomplishment when I captured my first lightening bolt. Good topic. And congratulations. I''m not crazy about the purple tone though.', '2008-06-20 13:24:36.000000', NULL, 1),
(4777699, 689499, 66384, '<td valign="top">Beautiful shot. This looks a lot like MaryO''s photography, with that beautiful water.</td>', 'Beautiful shot. This looks a lot like MaryO''s photography, with that beautiful water.', '2008-06-20 13:26:13.000000', NULL, 1),
(4777710, 689027, 15291, '<td valign="top">This is a wonderful image, The color outstanding. The reflection is awesome! I do however seem to be having a time of it connecting the title, or the image to the challenge.Would have scored this much higher if not for this.</td>', 'This is a wonderful image, The color outstanding. The reflection is awesome! I do however seem to be having a time of it connecting the title, or the image to the challenge.Would have scored this much higher if not for this.', '2008-06-20 13:31:28.000000', NULL, 1),
(4777724, 689775, 66384, '<td valign="top">I think this is an excellent idea and a good composition. I think a dark background with high contrast would make it stronger. Either dark paneling or just a black backdrop would help.  The gray patterned chair is busy and the smoke gives the image a washed out feeling. Also there is a little spot in the upper right corner that should be cloned out to eliminate that distraction. You did a good job of capturing the fire.</td>', 'I think this is an excellent idea and a good composition. I think a dark background with high contrast would make it stronger. Either dark paneling or just a black backdrop would help.  The gray patterned chair is busy and the smoke gives the image a washed out feeling. Also there is a little spot in the upper right corner that should be cloned out to eliminate that distraction. You did a good job of capturing the fire.', '2008-06-20 13:37:49.000000', NULL, 1),
(4777732, 688800, 66384, '<td valign="top">Beautiful colors and luminosity.</td>', 'Beautiful colors and luminosity.', '2008-06-20 13:41:57.000000', NULL, 1),
(4777737, 688020, 66384, '<td valign="top">I think this would score better if you used the full size of 640 pixels at 72 dpi. There is a tutorial under Learn on how to prepare the photo for entry in a challenge. But that aside, I like the photo. The sun rays are great, and the hammock and setting are good symbols of success. I think with some post processing work to bring out the colors and contrast, this could be very effective.</td>', 'I think this would score better if you used the full size of 640 pixels at 72 dpi. There is a tutorial under Learn on how to prepare the photo for entry in a challenge. But that aside, I like the photo. The sun rays are great, and the hammock and setting are good symbols of success. I think with some post processing work to bring out the colors and contrast, this could be very effective.', '2008-06-20 13:49:48.000000', NULL, 1),
(4777738, 689604, 66384, '<td valign="top">Terrific shot and perfect for the challenge. As a post challenge improvement, I would remove the white tower in the center and the white sign on the left.</td>', 'Terrific shot and perfect for the challenge. As a post challenge improvement, I would remove the white tower in the center and the white sign on the left.', '2008-06-20 13:51:31.000000', NULL, 1),
(4777740, 689775, 46832, '<td valign="top">The bill is too obviously a photo copy.</td>', 'The bill is too obviously a photo copy.', '2008-06-20 13:52:58.000000', NULL, 1),
(4777741, 689642, 66384, '<td valign="top">My favorite so far. I love the colors and the textures and the light. The focus and moment of capture are perfect. And I like the fact that this is a real, unstaged, success.</td>', 'My favorite so far. I love the colors and the textures and the light. The focus and moment of capture are perfect. And I like the fact that this is a real, unstaged, success.', '2008-06-20 13:54:18.000000', NULL, 1),
(4777743, 689786, 66384, '<td valign="top">Ah, beautiful horse, beautiful ribbons and very nice image. Congratulations.</td>', 'Ah, beautiful horse, beautiful ribbons and very nice image. Congratulations.', '2008-06-20 13:55:54.000000', NULL, 1),
(4777744, 689684, 66384, '<td valign="top">Love the pattern. Excellent depiction of success.</td>', 'Love the pattern. Excellent depiction of success.', '2008-06-20 13:57:37.000000', NULL, 1),
(4777746, 688987, 66384, '<td valign="top">Excellent. Just wish the horizon was straight.</td>', 'Excellent. Just wish the horizon was straight.', '2008-06-20 14:00:30.000000', NULL, 1),
(4777748, 689767, 66384, '<td valign="top">I don''t usually complain about noise, but this is such a nice image, I wish you had removed the noise</td>', 'I don''t usually complain about noise, but this is such a nice image, I wish you had removed the noise', '2008-06-20 14:02:20.000000', NULL, 1),
(4777752, 689606, 66384, '<td valign="top">WOW! gorgeous.</td>', 'WOW! gorgeous.', '2008-06-20 14:05:03.000000', NULL, 1),
(4777753, 689508, 66384, '<td valign="top">And I have one and I like it. Nice composition here.</td>', 'And I have one and I like it. Nice composition here.', '2008-06-20 14:07:56.000000', NULL, 1),
(4777757, 689794, 66384, '<td valign="top">Ah, lovely. Nice light and I like the soft texture.</td>', 'Ah, lovely. Nice light and I like the soft texture.', '2008-06-20 14:10:42.000000', NULL, 1),
(4777851, 689009, 66384, '<td valign="top">This is a terrific image, but it doesn''t say success to me. It is a great shot of power and/or precision, and I guess that is a measure of success. Just taking time to think this through, because I like the photo.</td>', 'This is a terrific image, but it doesn''t say success to me. It is a great shot of power and/or precision, and I guess that is a measure of success. Just taking time to think this through, because I like the photo.', '2008-06-20 15:26:29.000000', NULL, 1),
(4777894, 689736, 83934, '<td valign="top">Great photo, the guys smiling in the mid-ground is a little distracting but overall a good shot</td>', 'Great photo, the guys smiling in the mid-ground is a little distracting but overall a good shot', '2008-06-20 15:52:20.000000', NULL, 1),
(4777896, 689804, 83934, '<td valign="top">cropped perfectly, white balance a little cool but a great picture</td>', 'cropped perfectly, white balance a little cool but a great picture', '2008-06-20 15:52:53.000000', NULL, 1),
(4777899, 688020, 83934, '<td valign="top">I like the lens flare, not too clear, but looks quite relaxing. Would consider a black and white</td>', 'I like the lens flare, not too clear, but looks quite relaxing. Would consider a black and white', '2008-06-20 15:54:01.000000', NULL, 1),
(4777901, 689467, 94073, '<td valign="top">I gave this a 10...great idea...and we all really view this as success...otherwise we wouldn''t entre challenges.<br/> <br/>good job</td>', 'I gave this a 10...great idea...and we all really view this as success...otherwise we wouldn''t entre challenges. good job', '2008-06-20 15:54:20.000000', NULL, 1),
(4777905, 689547, 83934, '<td valign="top">nice use of macro photography, and depth of field. good job</td>', 'nice use of macro photography, and depth of field. good job', '2008-06-20 15:54:36.000000', NULL, 1),
(4777908, 689775, 94073, '<td valign="top">I voted this a five...would have been higher...but the bill is obviously a fake...the printing on the 100 is really light.<br/> <br/> <br/>Great idea tho!</td>', 'I voted this a five...would have been higher...but the bill is obviously a fake...the printing on the 100 is really light.  Great idea tho!', '2008-06-20 15:55:45.000000', NULL, 1),
(4777909, 688795, 83934, '<td valign="top">using a flash in this scene is a little contrasty and distracting. probably would have used the year as the focal point with some ambient light and finishing up with a narrower depth of field</td>', 'using a flash in this scene is a little contrasty and distracting. probably would have used the year as the focal point with some ambient light and finishing up with a narrower depth of field', '2008-06-20 15:55:55.000000', NULL, 1),
(4777912, 689792, 83934, '<td valign="top">This has always been a challenge. good clarity and depth of field.</td>', 'This has always been a challenge. good clarity and depth of field.', '2008-06-20 15:56:28.000000', NULL, 1),
(4777915, 689604, 83934, '<td valign="top">very nice contrast between the blue sky and the pool. It seems like the blue chairs ties it all in together. Is this depicting success as having your own remote beach and pool?</td>', 'very nice contrast between the blue sky and the pool. It seems like the blue chairs ties it all in together. Is this depicting success as having your own remote beach and pool?', '2008-06-20 15:57:50.000000', NULL, 1),
(4777918, 688751, 83934, '<td valign="top">You must have been using an underwater enclosure, one drop and the cameras history. good clarity</td>', 'You must have been using an underwater enclosure, one drop and the cameras history. good clarity', '2008-06-20 15:58:59.000000', NULL, 1),
(4777919, 688550, 66384, '<td valign="top">Cool, with these "window boxes" there can be many more corner offices than just the four corners of the building. Nice image. I like the geometry and lines.</td>', 'Cool, with these "window boxes" there can be many more corner offices than just the four corners of the building. Nice image. I like the geometry and lines.', '2008-06-20 15:59:33.000000', NULL, 1),
(4777920, 689813, 83934, '<td valign="top">cool angle. The red color cast is a little distracting but the idea overall is great</td>', 'cool angle. The red color cast is a little distracting but the idea overall is great', '2008-06-20 15:59:42.000000', NULL, 1),
(4777923, 689586, 83934, '<td valign="top">Is the car in the background a real car or a model? not keen on the composition</td>', 'Is the car in the background a real car or a model? not keen on the composition', '2008-06-20 16:01:02.000000', NULL, 1),
(4777924, 689786, 83934, '<td valign="top">Horses are such graceful animals, probably would have tried using a fill flash or high speed sync, just to make the picture pop and also to catch some life in the eyes of both subjects.</td>', 'Horses are such graceful animals, probably would have tried using a fill flash or high speed sync, just to make the picture pop and also to catch some life in the eyes of both subjects.', '2008-06-20 16:02:26.000000', NULL, 1),
(4777929, 689305, 83934, '<td valign="top">composition needs work and depth of field is distracting. an angled shot on this one may have given a little more to the picture.</td>', 'composition needs work and depth of field is distracting. an angled shot on this one may have given a little more to the picture.', '2008-06-20 16:03:36.000000', NULL, 1),
(4777931, 689814, 83934, '<td valign="top">The car/suv in the background is very distracting. beautiful horse and definitely a prestigious award, but would have been better if the depth of field really focused on the subject.</td>', 'The car/suv in the background is very distracting. beautiful horse and definitely a prestigious award, but would have been better if the depth of field really focused on the subject.', '2008-06-20 16:05:12.000000', NULL, 1),
(4777933, 689676, 83934, '<td valign="top">This would have been a wonderful picture if the subject was in complete focus. I bet if this shot were taken at a different location around the arena that it would have really popped.</td>', 'This would have been a wonderful picture if the subject was in complete focus. I bet if this shot were taken at a different location around the arena that it would have really popped.', '2008-06-20 16:07:03.000000', NULL, 1),
(4777937, 689606, 83686, '<td valign="top">awesome shot but does this really meet the challenge?</td>', 'awesome shot but does this really meet the challenge?', '2008-06-20 16:08:14.000000', NULL, 1),
(4777939, 689334, 83934, '<td valign="top">This is a very tough shot to get, Good Job! I really like the colors and the darkening around the trees.</td>', 'This is a very tough shot to get, Good Job! I really like the colors and the darkening around the trees.', '2008-06-20 16:08:20.000000', NULL, 1),
(4777945, 689704, 83934, '<td valign="top">I passed by this shot the first time, but when it came back around....I really think the description of this picture really gives it justice. Great job! The only thing I think that would have made this shot supreme would have been by using a narrower depth of field, really focusing on the subject.</td>', 'I passed by this shot the first time, but when it came back around....I really think the description of this picture really gives it justice. Great job! The only thing I think that would have made this shot supreme would have been by using a narrower depth of field, really focusing on the subject.', '2008-06-20 16:11:23.000000', NULL, 1),
(4777952, 689247, 83934, '<td valign="top">A really good shot of lightning, almost too close for sure. My question, how did you get the lightning to stay still for this shot? Just kidding, good job!</td>', 'A really good shot of lightning, almost too close for sure. My question, how did you get the lightning to stay still for this shot? Just kidding, good job!', '2008-06-20 16:14:35.000000', NULL, 1),
