(4781892, 689775, 94931, '<td valign="top">The background really lets this photo down. It would also be better if the smoke were to the side of his face, instead of clouding in front of his face.</td>', 'The background really lets this photo down. It would also be better if the smoke were to the side of his face, instead of clouding in front of his face.', '2008-06-23 16:40:04.000000', NULL, 1),
(4781897, 688292, 94931, '<td valign="top">That Lexus decal needs to be perfectly clean - there are spots on it. Also, you are visible in the left portion of the chrome. You could try draping a white sheet over you, except for the camera, to remove you from the shot.</td>', 'That Lexus decal needs to be perfectly clean - there are spots on it. Also, you are visible in the left portion of the chrome. You could try draping a white sheet over you, except for the camera, to remove you from the shot.', '2008-06-23 16:42:38.000000', NULL, 1),
(4781903, 688800, 94931, '<td valign="top">This is a great photo, but once again, as with most of these photos submitted in this "success" competition, it just relies too much on the actual title of the photo than the content of the photo.</td>', 'This is a great photo, but once again, as with most of these photos submitted in this "success" competition, it just relies too much on the actual title of the photo than the content of the photo.', '2008-06-23 16:48:33.000000', NULL, 1),
